 باشد؛ بااین‌حال دفترچه همان سری ساخت ملاک نهایی است.</p><h3>پرسش‌های متداول</h3><p><strong>ظرفیت فریزر چقدر است؟</strong><br>۲۰ فوت معادل ۱۷۹ لیتر طبق منبع ثبت‌شده.</p><p><strong>درب از کدام سمت باز می‌شود؟</strong><br>در منبع، بازشدن درب به سمت چپ ذکر شده است.</p><p><strong>آیا کالا موجود است؟</strong><br>خیر؛ ناموجود است.</p><h3>منبع بررسی</h3><p><a href="'.esc_url($u).'" target="_blank" rel="nofollow noopener">صفحه مدل F20H در فروشگاه منبع</a></p>';$p->set_name('فریزر امرسان مدل F20H ظرفیت ۲۰ فوت');$p->set_status('draft');$p->set_catalog_visibility('hidden');$p->set_stock_status('outofstock');$p->set_description($d);$p->set_short_description('فریزر امرسان مدل F20H ظرفیت ۲۰ فوت / ۱۷۹ لیتر · ۷ کشو · No Frost · ناموجود');$p->save();wp_set_object_terms($id,'یخچال و فریزر','product_cat',false);wp_set_object_terms($id,'امرسان','pa_brand',false);foreach(['_bhc_model'=>'F20H','_bhc_brand_latin'=>'Emersun','_bhc_source_url'=>$u,'_bhc_source_type'=>'exact_retailer_page','_bhc_source_checked_at'=>'2026-11-20','_bhc_source_evidence'=>$u.' | مدل، ظرفیت، انرژی، برفک‌زدایی، ابعاد، وزن، طبقات، کشوها، جهت درب و شناسه کالا بررسی شد.','_bhc_structured_specs'=>wp_json_encode($spec,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'_bhc_highlights'=>implode("\n",array_slice(array_values($spec),0,12)),'_bhc_faq'=>'ظرفیت چقدر است؟ | ۲۰ فوت / ۱۷۹ لیتر.\nآیا No Frost است؟ | طبق منبع، بله.\nآیا موجود است؟ | خیر.','_bhc_seo_title'=>'فریزر امرسان F20H ظرفیت ۲۰ فوت | مشخصات کامل | ناموجود','_bhc_seo_description'=>'مشخصات فریزر امرسان F20H شامل ظرفیت ۱۷۹ لیتر، ۷ کشو، No Frost، ابعاد و وزن؛ وضعیت ناموجود در بهاران هوم.','_bhc_verification_status'=>'verified_reference','_bhc_catalog_quality_state'=>'reference_verified','_bhc_image_generation_status'=>'awaiting_product_reference'] as $k=>$v)update_post_meta($id,$k,$v);update_option('bhc_catalog_emersun_f20h_v284',['id'=>$id,'at'=>current_time('mysql')],false);},284);
